style.css:
@-moz-document url-prefix("https://www.roblox.com") {
/* Set the background on the highest possible element (html) and the body */
  html, body {
    background-image: url('https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExczBpdWI1M3hyeDYxcXFwZTN0bTV3NHdwaTd6b3c2Y2o3aTVpd3lsNiZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/10gSu8dYVI83te/giphy.gif') !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-color: transparent !important; /* Ensure body itself is transparent */
  }

  /* Make ALL elements that could have a background transparent by default */
  /* This is very broad and might cause some display issues but aims to reveal the background */
  * {
    background-color: transparent !important;
    box-shadow: none !important; /* Remove shadows that might obscure */
    border-color: rgba(255, 255, 255, 0.2) !important; /* Make borders semi-transparent */
  }

  /* Specific Roblox layout elements that often have strong default backgrounds */
  #container-main, #wrapper, #content, #main-content, .content, .container-fluid,
  .section-content, .card, .layout-main, .rbx-body, .rbx-container,
  .roblox-body, .roblox-container, .grid-item, .item-card, .game-card,
  .profile-card, .text-box, .btn-secondary, .form-control {
    background-color: transparent !important;
  }

  /* Ensure readability of text across the site by forcing a light color */
  p, span, a, h1, h2, h3, h4, h5, h6, li, div, button, input, textarea {
    color: #ffffff !important; /* Force white text */
  }

  /* Ensure links remain clickable and somewhat visible */
  a {
    text-decoration: underline !important;
  }

  /* Adjust header/footer/nav elements if they still block the view */
  .header, .footer, .navbar, .nav-menu {
    background-color: rgba(0, 0, 0, 0.6) !important; /* Make headers/footers semi-transparent dark */
  }
}
